# repeatable seed via deterministic UUID from stable strings
import uuid
for i,x in enumerate(Q):
 qid=str(uuid.uuid5(uuid.NAMESPACE_URL,f'pyprep-v1-question-{i+1}'))
 out.append(f'insert into public.questions(id,topic_id,body,code,difficulty,explanation,source,verified) values ({sql(qid)},{sql(x["topic"])},{sql(x["body"])},{"null" if not x["code"] else sql(x["code"])},{sql("medium" if x["code"] else "easy")},{sql(x["explanation"])},{sql("Tổng hợp theo chuyên đề từ bộ PDF IPPA233277; câu hỏi biên soạn mới")},true) on conflict(id) do update set topic_id=excluded.topic_id,body=excluded.body,code=excluded.code,explanation=excluded.explanation,verified=true;')
 for j,opt in enumerate(x['options']):
  oid=str(uuid.uuid5(uuid.NAMESPACE_URL,f'pyprep-v1-option-{i+1}-{j}'))
  out.append(f'insert into public.question_options(id,question_id,label,body,is_correct) values ({sql(oid)},{sql(qid)},{sql("ABCD"[j])},{sql(opt)},{"true" if j==x["answer"] else "false"}) on conflict(question_id,label) do update set body=excluded.body,is_correct=excluded.is_correct;')
out.append('commit;')
Path('/mnt/data/python-exam-v1/supabase/02_seed_questions.sql').write_text('\n'.join(out)+'\n')
Path('/mnt/data/python-exam-v1/scripts/bank_summary.json').write_text(json.dumps({'total':len(Q),'by_topic':{t:sum(z['topic']==t for z in Q) for t,_,_ in T}},ensure_ascii=False,indent=2))
print('questions',len(Q))
